using namespace std;

int main()
{
    bool quit = false;
    string text = "";
    cout << "Please enter a sentence:";
    getline(cin, text);
    int choice = 1;
    while (!quit) {
        cout << "1. Show text\n2. Show length\n3. Show first and last character\n4. Find a word\n5. Extract a part(substring)\n6. Replace the text with a new sentence\n7. qiut" << endl;
        cout << "Your choice:";
        cin >> choice;
        while (choice < 1 || choice>7) {
            cout << "Invalid, please enter again.";
            cout << "Your choice:";
            cin >> choice;
        }
        if (choice == 1) {
            cout << text << endl;
        }
        else if (choice == 2) {
            cout << text.length() << endl;
        }
        else if (choice == 3) {
            if (text.length() == 0) {
                cout << "Text is empty";
            }
            else {
                cout << "The first letter is '" << text[0] << "' and the last letter is '" << text[text.length() - 1] << "'" << endl;
            }
        }
        else if (choice == 4) {
            string word="";
            cout << "Enter the word you are looking for:";
            cin >> word;
            if (text.find(word) == string::npos) {
                cout << "Word not found." << endl;
            }
            else {
                cout << "The index of the word you are looking for is " << text.find(word) << endl;
            }
        }
        else if (choice == 5) {
            int start = 0;
            int partLength = 0;
            cout << "Enter the start index:";
            cin >> start;
            cout << "Enter the length of the part:";
            cin >> partLength;
            while (start < 0 || start >= text.length() || partLength + start > text.length() || partLength <= 0) {
                cout << "Invalid, please enter it again." << endl;
                cout << "Enter the start index:";
                cin >> start;
                cout << "Enter the length of the part:";
                cin >> partLength;
            }
            cout << "The part you extracted is '" << text.substr(start, partLength) << "'" << endl;
        }
        else if (choice == 6) {
            cout << "Please enter your new sentence:";
            cin.ignore();
            getline(cin, text);
        }
        else if (choice == 7) {
            cout << "Goodbye!";
            quit = true;
        }
    }
}

