#include <iostream>
using namespace std;

void inputScores(int arr[], int size);
void displayScores(int arr[], int size);
double calculateAverage(int arr[], int size);
int findHighest(int arr[], int size);
int findLowest(int arr[], int size);
void updateScore(int arr[], int size);
bool isPassing(int score);

int main() {
    int size;
    int scores[50];
    int choice;

    cout << "How many students? ";
    cin >> size;

    while (size < 1 || size > 50) {
        cout << "Invalid number. Enter between 1 and 50: ";
        cin >> size;
    }

    do {
        cout << "\nMenu\n";
        cout << "1. Enter Scores\n";
        cout << "2. Display Scores\n";
        cout << "3. Calculate Average\n";
        cout << "4. Highest Score\n";
        cout << "5. Lowest Score\n";
        cout << "6. Update Score\n";
        cout << "7. Check if Student Passed\n";
        cout << "8. Quit\n";
        cout << "Choice: ";
        cin >> choice;

        if (choice == 1) {
            inputScores(scores, size);
        }
        else if (choice == 2) {
            displayScores(scores, size);
        }
        else if (choice == 3) {
            cout << "Average: " << calculateAverage(scores, size) << endl;
        }
        else if (choice == 4) {
            cout << "Highest Score: " << findHighest(scores, size) << endl;
        }
        else if (choice == 5) {
            cout << "Lowest Score: " << findLowest(scores, size) << endl;
        }
        else if (choice == 6) {
            updateScore(scores, size);
        }
        else if (choice == 7) {
            int student;
            cout << "Enter student number (1-" << size << "): ";
            cin >> student;

            if (student >= 1 && student <= size) {
                if (isPassing(scores[student - 1]))
                    cout << "Student is passing.\n";
                else
                    cout << "Student is failing.\n";
            }
            else {
                cout << "Invalid student number.\n";
            }
        }
        else if (choice == 8) {
            cout << "BYE!\n";
        }
        else {
            cout << "Invalid choice.\n";
        }

    } while (choice != 8);

    return 0;
}


void inputScores(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        cout << "Enter score for student " << i + 1 << ": ";
        cin >> arr[i];
    }
}

void displayScores(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        cout << "Student " << i + 1 << ": " << arr[i] << endl;
    }
}

double calculateAverage(int arr[], int size) {
    int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    return (double)sum / size;
}

int findHighest(int arr[], int size) {
    int highest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > highest) {
            highest = arr[i];
        }
    }
    return highest;
}

int findLowest(int arr[], int size) {
    int lowest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] < lowest) {
            lowest = arr[i];
        }
    }
    return lowest;
}

void updateScore(int arr[], int size) {
    int student;
    cout << "Enter student number (1-" << size << "): ";
    cin >> student;

    if (student >= 1 && student <= size) {
        cout << "Enter new score: ";
        cin >> arr[student - 1];
        cout << "Score updated.\n";
    }
    else {
        cout << "Invalid student number.\n";
    }
}

bool isPassing(int score) {
    return score >= 50;
}

